// ====== CONFIGURAÇÃO (é aqui que se ajusta) ======
const duracaoMin = 90;
const offset = '-03:00';
const fusoHorario = 'America/Sao_Paulo';

// Períodos de atendimento por dia da semana.
// 0 = domingo, 1 = segunda, 2 = terça, 3 = quarta, 4 = quinta, 5 = sexta, 6 = sábado.
// Valores de EXEMPLO: troque pelos reais da página de agendamento.
const atendimento = {
  1: [['08:00', '12:00'], ['14:00', '18:00']],   // segunda
  2: [['08:00', '12:00'], ['14:00', '18:00']],   // terça
  5: [['08:00', '12:00']],                        // sexta
};
// ==================================================

// Data pedida (vem do nó Entrada)
const data = $('Entrada').first()?.json?.data;
const formatoOk = /^\d{4}-\d{2}-\d{2}$/.test(String(data ?? ''));
const meioDia = new Date(`${data}T12:00:00${offset}`);

if (!formatoOk || isNaN(meioDia)) {
  return [{ json: {
    erro: 'Data inválida ou ausente. Envie no formato AAAA-MM-DD, por exemplo 2026-11-03.',
    horarios_livres: [],
  } }];
}

const diaSemana = meioDia.getUTCDay();
const periodos = atendimento[diaSemana] ?? [];   // dia sem atendimento = lista vazia
const toDate = (hhmm) => new Date(`${data}T${hhmm}:00${offset}`);

// Eventos que já ocupam a agenda
const ocupados = $input.all().map(i => {
  const e = i.json;
  if (e.status === 'cancelled') return { ini: NaN, fim: NaN };
  if (e.start?.date && !e.start?.dateTime) {   // evento de dia inteiro
    return {
      ini: new Date(`${e.start.date}T00:00:00${offset}`),
      fim: new Date(`${e.end.date}T00:00:00${offset}`),
    };
  }
  return { ini: new Date(e.start?.dateTime), fim: new Date(e.end?.dateTime) };
}).filter(o => !isNaN(o.ini) && !isNaN(o.fim));

// Gera os horários e tira os que já passaram ou batem com eventos
const passo = duracaoMin * 60000;
const agora = new Date();
const livres = [];
for (const [ini, fim] of periodos) {
  for (let t = toDate(ini).getTime(); t + passo <= toDate(fim).getTime(); t += passo) {
    const s = new Date(t), f = new Date(t + passo);
    const conflita = ocupados.some(o => s < o.fim && f > o.ini);
    if (!conflita && s > agora) {
      livres.push(s.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: fusoHorario }));
    }
  }
}

return [{ json: {
  data,
  dia_semana: diaSemana,
  duracao_min: duracaoMin,
  horarios_livres: livres,
  mensagem: livres.length
    ? `Horários livres em ${data}: ${livres.join(', ')}`
    : `Não há horários livres em ${data}.`,
} }];
